// i18n (the permanent bilingual rule): English by default, Spanish available. Nothing hardcoded in the screens.
import i18n from 'i18next';
import { initReactI18next } from 'react-i18next';
import en from './en.json';
import es from './es.json';
// i18n bundle from the ENGINE (generated by `career_test --dump-strings`, a flat string table from strings.cpp).
// Resolves the keys the engine emits as-is (inbox from/subject, times, championships...), which
// the app surfaces via t(). Merged UNDER the app's own curated keys (those win on collision).
import engineEn from './engine.en.json';
import engineEs from './engine.es.json';

// The eleven translated languages are DATA: one flat file per language in locales/, loaded by glob. Adding
// a language is dropping in a file, without touching this module — which is what lets the community
// contribute in zta-releases without going through code. EN and ES still come from the curated bundles.
const extra = import.meta.glob('./locales/*.json', { eager: true }) as Record<
  string, { default: Record<string, string> }>;

export const LOCALES = ['en', 'es', 'de', 'it', 'ru', 'ko', 'fr', 'zh-Hans', 'pt', 'pt-BR', 'tr', 'pl', 'hu'] as const;
export type Locale = (typeof LOCALES)[number];

export const LOCALE_LABELS: Record<Locale, string> = {
  en: 'English', es: 'Español', de: 'Deutsch', it: 'Italiano', ru: 'Русский',
  ko: '한국어', fr: 'Français', 'zh-Hans': '简体中文', pt: 'Português', 'pt-BR': 'Português (BR)',
  tr: 'Türkçe', pl: 'Polski', hu: 'Magyar',
};

// Comparison WITHOUT distinguishing case: language tags are conventionally
// case-insensitive (BCP 47), and this function is exactly where a persisted locale is reread. It returns
// the CANONICAL spelling from LOCALES, not the one that arrived (e.g. 'pt-br' -> 'pt-BR').
//
// And it understands the REGION, which is where the real tags of an operating system come from. Before it
// only matched the exact tag, so `de-DE`, `ko-KR`, `zh-CN` and `pt-PT` all fell back to English
// —that is, everyone except whoever had the language written exactly like us—. It did not bite
// as long as the only thing reread was a code of ours already canonical, but it is exactly what
// `detectLocale()` feeds it.
export function normalizeLocale(v: string): Locale {
  const raw = String(v ?? '').trim();
  const exact = LOCALES.find((l) => l.toLowerCase() === raw.toLowerCase());
  if (exact) return exact;                    // 'pt-BR', 'pt_br', 'ZH-HANS'…
  const parts = raw.toLowerCase().split(/[-_]/).filter(Boolean);
  const base = parts[0];
  if (!base) return 'en';
  // Portuguese: the Brazilian one is a separate file, and is only chosen if the tag says so.
  if (base === 'pt') return parts.includes('br') ? 'pt-BR' : 'pt';
  // Chinese: the mod only ships Simplified. For a Traditional reader Simplified serves LESS
  // than English —they are different writing systems, not a spelling variant—, so the
  // tags that declare Traditional stay in English instead of receiving a Chinese they cannot read.
  if (base === 'zh') {
    const hant = ['hant', 'tw', 'hk', 'mo'].some((t) => parts.includes(t));
    return hant ? 'en' : 'zh-Hans';
  }
  return LOCALES.find((l) => l.toLowerCase() === base) ?? 'en';
}

// The language the player already has set on their machine, so as NOT to start in English someone who
// never chose English. Only used when creating a new config: a saved choice always wins.
//
// `navigator.languages` is walked in order of preference and not just `navigator.language`, because a
// system with “Catalan, Spanish, English” has to end up in Spanish and not in English. A language we
// do not translate does not cut the walk short; an explicit English does, because there the player DID choose.
export function detectLocale(): Locale {
  const nav: Navigator | undefined = typeof navigator === 'undefined' ? undefined : navigator;
  const tags = [...(nav?.languages ?? []), nav?.language].filter(Boolean) as string[];
  for (const tag of tags) {
    const hit = normalizeLocale(tag);
    if (hit !== 'en' || /^en(\b|[-_])/i.test(tag)) return hit;
  }
  return 'en';
}

// i18next supports nested namespacing (en.json carries "app": {...}, "crash": {...}): the value of a
// key is not always a string. Record<string, unknown> reflects that; before it said Record<string,
// string> and tsc accepted it only because nobody ran `tsc --noEmit` on this file (Task 6).
function resources(): Record<string, { translation: Record<string, unknown> }> {
  const out: Record<string, { translation: Record<string, unknown> }> = {
    en: { translation: { ...engineEn, ...en } },
    es: { translation: { ...engineEs, ...es } },
  };
  for (const [path, mod] of Object.entries(extra)) {
    const code = path.replace('./locales/', '').replace('.json', '');
    out[code] = { translation: mod.default };
  }
  return out;
}

export function initI18n(locale: Locale = 'en'): typeof i18n {
  // The <html lang> has to follow the chosen language. `index.html` leaves it pinned to "en" and nobody
  // touched it: with the app in German, the document kept declaring itself English. That is read by the screen reader
  // (which would pronounce German with English phonetics), the browser's word hyphenation and any
  // CSS `:lang()`. It is set here because it is the ONLY place a language change passes through.
  // The LOCALES tags are already valid BCP 47 as they are ('pt-BR', 'zh-Hans'), so they need no translating.
  if (typeof document !== 'undefined') document.documentElement.lang = normalizeLocale(locale);
  if (!i18n.isInitialized) {
    void i18n.use(initReactI18next).init({
      resources: resources(),
      lng: normalizeLocale(locale),
      // pt-BR is saved in full, but if a key is missing Portuguese is preferred over English.
      fallbackLng: { 'pt-BR': ['pt', 'en'], default: ['en'] },
      interpolation: { escapeValue: false },
    });
  } else {
    void i18n.changeLanguage(normalizeLocale(locale));
  }
  return i18n;
}

// {key} interpolation for ENGINE templates (its own single-brace syntax, NOT i18next's {{...}}).
// An exact mirror of career::MailInterpolate: ANY {...} is a placeholder (the engine doesn't validate
// the key's contents — it just looks for '{' and the '}' that follows); no
// value -> it's removed. The regex used to require [a-zA-Z_]+ and left orphaned braces like {x1} (digits) untouched.
export function interpEngine(text: string, params?: Record<string, string>): string {
  return text.replace(/\{([^}]*)\}/g, (_m, k: string) => params?.[k] ?? '');
}

// The twelve short months, in ONE string separated by bars instead of a JSON list.
//
// It is the only way for them to exist for the eight languages. The translation catalog flattens the
// English bundle with `flatten()` (tools/i18n/catalog.py), which discards EVERYTHING that is not text —
// so `identity.months` as a list was invisible to the kit, to the gate and to the sealing,
// and the eight languages showed the months in English without anything pointing it out. It was the only key in the
// corpus that was not text, i.e. the whole hole. As a string it is a normal key and travels on its own.
//
// As a bonus, the translator sees the twelve TOGETHER, which is exactly what is needed for the set to
// be coherent (not a “Jan” next to a “febrero”).
const MESES_EN = ['Jan', 'Feb', 'Mar', 'Apr', 'May', 'Jun', 'Jul', 'Aug', 'Sep', 'Oct', 'Nov', 'Dec'];

export function monthNames(t: (key: string) => string): string[] {
  const partes = String(t('identity.months') ?? '').split('|').map((m) => m.trim());
  // A broken translation cannot leave the months dropdown blank: if twelve do not come out, English.
  return partes.length === 12 && partes.every(Boolean) ? partes : MESES_EN;
}

export default i18n;
